// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawCallerIndex) public {
        vm.assume(depositAmount > 0 && depositAmount <= address(this).balance);
        address caller = address(uint160(uint256(keccak256(abi.encode(withdrawCallerIndex)))));
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(caller).balance;

        bool ok = false;
        vm.prank(caller);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(caller).balance;

        if (ok) {
            assertTrue(balanceAfter - balanceBefore == depositAmount);
        } else {
            assertTrue(true);
        }
    }
}
